    INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, "order")
    VALUES 
    (v_topic_id, 'Glomerular filtration rate is best defined as the:', '["Volume of plasma filtered into Bowman space per unit time", "Volume of urine excreted per unit time", "Volume of blood entering the kidney per minute", "Amount of sodium reabsorbed per minute", "Amount of creatinine secreted per minute"]', 0, 'GFR represents the sum of the filtration rates in all of the functioning nephrons.', 1),
    (v_topic_id, 'Inulin is an ideal marker for GFR because it is:', '["Filtered and completely reabsorbed", "Filtered and secreted", "Filtered but neither reabsorbed nor secreted", "Protein bound", "Metabolized in the kidney"]', 2, 'Since inulin is neither reabsorbed nor secreted by the tubules, its clearance is exactly equal to the GFR.', 2),
    (v_topic_id, 'Creatinine clearance slightly overestimates true GFR because creatinine is:', '["Completely reabsorbed", "Slightly secreted by the tubules", "Not filtered freely", "Bound strongly to plasma proteins", "Metabolized in Bowman space"]', 1, 'In humans, a small amount of creatinine (about 10-20%) is secreted in the proximal tubule.', 3),
    (v_topic_id, 'Para-aminohippuric acid (PAH) clearance is used to estimate:', '["GFR", "Filtration fraction", "Renal plasma flow", "Renal blood flow directly", "Free water clearance"]', 2, 'PAH is filtered and mostly secreted, essentially clearing the plasma of PAH in one pass.', 4),
    (v_topic_id, 'Filtration fraction is equal to:', '["Renal plasma flow / GFR", "GFR / renal plasma flow", "Urine flow / GFR", "GFR / renal blood flow", "Renal blood flow / renal plasma flow"]', 1, 'FF = GFR / RPF. It represents the portion of plasma filtered across the glomerular barrier.', 5),
    (v_topic_id, 'Which force favors glomerular filtration?', '["Bowman space hydrostatic pressure", "Glomerular capillary oncotic pressure", "Glomerular capillary hydrostatic pressure", "Plasma protein concentration", "Ureteral pressure"]', 2, 'Pressure inside the capillary pushed fluid out into the capsule.', 6),
    (v_topic_id, 'Which force opposes glomerular filtration?', '["Glomerular capillary hydrostatic pressure", "Bowman space hydrostatic pressure", "Filtration coefficient", "Afferent arteriolar dilation", "Renal plasma flow"]', 1, 'Fluid pressure inside the Bowman space pushes back against the incoming filtrate.', 7),
    (v_topic_id, 'An increase in plasma protein concentration will generally:', '["Increase GFR", "Decrease glomerular capillary oncotic pressure", "Decrease GFR", "Increase renal blood flow", "Increase urine flow directly"]', 2, 'Higher protein levels increase oncotic pressure, which keeps fluid in the capillaries.', 8),
    (v_topic_id, 'Acute ureteric obstruction decreases GFR primarily by increasing:', '["Glomerular hydrostatic pressure", "Bowman space hydrostatic pressure", "Renal plasma flow", "Filtration coefficient", "Aldosterone secretion"]', 1, 'Obstruction causes filtrate to back up, raising the pressure in the Bowman space.', 9),
    (v_topic_id, 'Constriction of the afferent arteriole will usually:', '["Increase GFR and increase renal blood flow", "Decrease GFR and decrease renal blood flow", "Increase GFR and decrease renal blood flow", "Decrease GFR and increase renal blood flow", "Leave GFR unchanged"]', 1, 'Restricting the "entry" reduces both the blood flow and the filtration pressure.', 10),
    (v_topic_id, 'Mild constriction of the efferent arteriole tends to:', '["Decrease glomerular capillary hydrostatic pressure", "Increase glomerular capillary hydrostatic pressure and help maintain GFR", "Increase renal blood flow markedly", "Decrease filtration fraction", "Decrease peritubular capillary oncotic pressure"]', 1, 'Restricting the "exit" creates back-pressure that favors filtration.', 11),
    (v_topic_id, 'Severe efferent arteriolar constriction may reduce GFR because it:', '["Lowers plasma oncotic pressure in glomerular capillaries", "Raises glomerular capillary oncotic pressure markedly", "Lowers Bowman space pressure", "Decreases proximal sodium reabsorption", "Inhibits renin release"]', 1, 'Extremely low flow allows proteins to concentrate heavily, raising the opposing oncotic pressure.', 12),
    (v_topic_id, 'Renal autoregulation is mainly mediated by:', '["Sympathetic stimulation and aldosterone", "Myogenic response and tubuloglomerular feedback", "ADH and ANP", "PTH and calcitonin", "Erythropoietin and renin"]', 1, 'These mechanisms keep GFR and RBF stable across varying pressures.', 13),
    (v_topic_id, 'The macula densa senses tubular concentration of:', '["Glucose", "Sodium chloride", "Urea", "Creatinine", "Bicarbonate only"]', 1, 'High NaCl signals high GFR; Low NaCl signals low GFR.', 14),
    (v_topic_id, 'Decreased NaCl delivery to the macula densa causes:', '["Decreased renin release", "Increased renin release", "Decreased afferent arteriolar dilation", "Increased ANP secretion", "Immediate decrease in aldosterone"]', 1, 'Low NaCl delivery triggers renin to raise system pressure and GFR.', 15),
    (v_topic_id, 'Renin is secreted by:', '["Podocytes", "Juxtaglomerular cells", "Mesangial cells", "Principal cells", "Intercalated cells"]', 1, 'JG cells are modified smooth muscle cells in the afferent arteriole.', 16),
    (v_topic_id, 'Angiotensin II preferentially constricts the:', '["Afferent arteriole", "Efferent arteriole", "Peritubular capillary", "Vasa recta only", "Renal vein"]', 1, 'This increases Glomerular Hydrostatic Pressure to preserve GFR during low-pressure states.', 17),
    (v_topic_id, 'The nephron segment responsible for the majority of sodium and water reabsorption is the:', '["Proximal tubule", "Thin descending limb", "Thick ascending limb", "Distal convoluted tubule", "Collecting duct"]', 0, 'About 67% of filtrate is reabsorbed in the proximal tubule.', 18),
    (v_topic_id, 'Glucose reabsorption in the proximal tubule occurs primarily via:', '["Passive diffusion only", "Na+-glucose cotransport", "ADH-sensitive water channels", "Na+-K+-2Cl− cotransport", "ENaC channels"]', 1, 'SGLT2 and SGLT1 are the main transporters.', 19),
    (v_topic_id, 'Bicarbonate reabsorption in the proximal tubule depends importantly on:', '["Aldosterone", "Carbonic anhydrase", "ANP", "PTH", "ADH"]', 1, 'CA is needed to convert H2CO3 to transportable H2O and CO2.', 20),
    (v_topic_id, 'Glucosuria develops when filtered glucose load exceeds the:', '["Renal plasma flow", "Tm for glucose reabsorption", "Filtration fraction", "Creatinine clearance", "Free water clearance"]', 1, 'The threshold where transporters are saturated.', 21),
    (v_topic_id, 'The gradual appearance of glucose in the urine before the exact transport maximum is fully reached is called:', '["Filtration fraction", "Splay", "Countercurrent exchange", "Clearance", "Osmotic equilibrium"]', 1, 'Splay is due to the natural variation in nephron lengths and transporter counts.', 22),
    (v_topic_id, 'The thick ascending limb of the loop of Henle:', '["Is permeable to water", "Reabsorbs NaCl and is impermeable to water", "Reabsorbs glucose", "Is the main site of ADH action", "Secretes potassium into urine as its main role"]', 1, 'This segment is crucial for the "Single Effect" in concentration.', 23),
    (v_topic_id, 'The descending limb of the loop of Henle is relatively:', '["Impermeable to water", "Permeable to water", "Impermeable to sodium and water", "Main site of aldosterone action", "Main site of glucose transport"]', 1, 'Water leaves the tubule into the concentrated medulla here.', 24),
    (v_topic_id, 'The corticomedullary osmotic gradient is generated primarily by:', '["Glomerular filtration", "Countercurrent multiplication", "Tubuloglomerular feedback", "Pressure natriuresis", "Renin secretion"]', 1, 'A cycle involving the Loop of Henle and Urea.', 25),
    (v_topic_id, 'The vasa recta function mainly to:', '["Generate the medullary gradient", "Preserve the medullary gradient by countercurrent exchange", "Filter plasma", "Reabsorb glucose", "Secrete ADH"]', 1, 'They act as exchangers to move water/salt without washing out the gradient.', 26),
    (v_topic_id, 'High blood flow through the vasa recta would tend to:', '["Preserve medullary hypertonicity", "Wash out the medullary gradient", "Increase maximal urine concentration", "Increase ADH secretion", "Increase GFR directly"]', 1, 'Rapid flow removes solute faster than it can be replaced.', 27),
    (v_topic_id, 'ADH acts mainly to increase water reabsorption in the:', '["Proximal tubule", "Thick ascending limb", "Distal convoluted tubule and collecting duct", "Bowman capsule", "Afferent arteriole"]', 2, 'It inserts Aquaporin-2 channels in the late nephron.', 28),
    (v_topic_id, 'ADH increases water permeability by promoting insertion of:', '["ENaC channels", "Aquaporin-2 channels", "Na+/K+ ATPase in glomerulus", "SGLT transporters", "NKCC transporters in collecting duct"]', 1, 'Specific apical water channels.', 29),
    (v_topic_id, 'Increased plasma osmolality is a strong stimulus for:', '["Reduced ADH release", "Increased ADH release", "Reduced thirst", "Increased ANP release", "Reduced aldosterone release"]', 1, 'The body tries to retain water to dilute the concentrated blood.', 30),
    (v_topic_id, 'After a large water load in a healthy person, the kidneys should produce urine that is:', '["Small volume and concentrated", "Large volume and dilute", "Protein rich", "Glucose rich", "Maximally hypertonic"]', 1, 'Diluting the urine allows for excess water excretion.', 31),
    (v_topic_id, 'Aldosterone acts mainly on:', '["Proximal tubule cells", "Principal cells of the late distal tubule and collecting duct", "Podocytes", "Macula densa cells", "Thin descending limb cells"]', 1, 'Targets the ENaC and ROMK channels.', 32),
    (v_topic_id, 'Aldosterone increases:', '["Sodium excretion and potassium retention", "Sodium reabsorption and potassium secretion", "Water reabsorption independently of sodium", "Glucose secretion", "Calcium excretion"]', 1, 'The "salt-saving" hormone.', 33),
    (v_topic_id, 'Hyperkalemia directly stimulates release of:', '["ADH", "Aldosterone", "ANP", "Renin", "Erythropoietin"]', 1, 'Potassium acts directly on the adrenal cortex.', 34),
    (v_topic_id, 'ANP is released in response to:', '["Decreased atrial stretch", "Increased atrial stretch", "Hyperkalemia", "Low plasma osmolality", "Low sodium intake only"]', 1, 'Stretch indicates volume overload.', 35),
    (v_topic_id, 'ANP tends to:', '["Promote sodium retention", "Promote natriuresis", "Increase aldosterone release", "Increase renin release", "Increase ADH-mediated water reabsorption"]', 1, 'Natriuresis is the excretion of sodium in urine.', 36),
    (v_topic_id, 'Which nephron segment is the main site of PTH-stimulated calcium reabsorption?', '["Proximal tubule", "Thin descending limb", "Thick ascending limb", "Distal convoluted tubule", "Collecting duct"]', 3, 'PTH acts on DCT to increase Ca2+ reabsorption.', 37),
    (v_topic_id, 'PTH decreases phosphate reabsorption primarily in the:', '["Distal convoluted tubule", "Collecting duct", "Proximal tubule", "Thin ascending limb", "Vasa recta"]', 2, 'The "Phosphate Trashing Hormone".', 38),
    (v_topic_id, 'PTH stimulates renal formation of:', '["25-hydroxyvitamin D", "1,25-dihydroxyvitamin D", "Aldosterone", "Renin", "ANP"]', 1, 'Activates 1-alpha-hydroxylase.', 39),
    (v_topic_id, 'In metabolic acidosis, the immediate respiratory compensation is:', '["Hypoventilation", "Hyperventilation", "Increased aldosterone", "Increased ADH", "Reduced ammonium excretion"]', 1, 'Blowing off CO2 raises the blood pH.', 40),
    (v_topic_id, 'In chronic metabolic acidosis, the kidney compensates by increasing:', '["Bicarbonate excretion", "Hydrogen ion excretion and new bicarbonate generation", "Glucose excretion", "Calcium excretion only", "Urea excretion only"]', 1, 'Via ammonium and titratable acid excretion.', 41),
    (v_topic_id, 'In chronic respiratory acidosis, renal compensation includes:', '["Reduced bicarbonate reabsorption", "Increased bicarbonate reabsorption and acid excretion", "Reduced hydrogen secretion", "Increased glucose reabsorption", "Decreased ammonium production"]', 1, 'The kidney keeps bicarb to balance the high CO2.', 42),
    (v_topic_id, 'New bicarbonate is generated in part through increased:', '["Glucose filtration", "Ammonium excretion", "Sodium secretion", "PAH clearance", "Urea filtration only"]', 1, 'Each NH4+ excreted results in a "new" bicarbonate ion added to blood.', 43),
    (v_topic_id, 'Acidemia tends to shift potassium:', '["Into cells", "Out of cells", "Into bone", "Into urine immediately", "Into RBCs only"]', 1, 'H+ moves in, K+ moves out to maintain electrical balance.', 44),
    (v_topic_id, 'Hyperkalemia is dangerous primarily because of its effects on:', '["Bone mineralization", "Cardiac membrane excitability", "Glucose filtration", "Urea synthesis", "Erythropoietin secretion"]', 1, 'High K+ depolarizes heart cells, which can stop the heart.', 45),
    (v_topic_id, 'If the clearance of a substance equals inulin clearance, that substance is:', '["Secreted", "Reabsorbed", "Filtered without net reabsorption or secretion", "Not filtered", "Bound to protein"]', 2, 'Clearance = GFR.', 46),
    (v_topic_id, 'A substance with clearance greater than inulin is likely:', '["Net reabsorbed", "Net secreted", "Not filtered", "A marker of filtration fraction", "Completely protein bound"]', 1, 'Clearance > GFR.', 47),
    (v_topic_id, 'A substance with clearance less than inulin is likely:', '["Net secreted", "Net reabsorbed", "A marker of renal plasma flow", "Not filtered and fully secreted", "Equal to creatinine always"]', 1, 'Clearance < GFR.', 48),
    (v_topic_id, 'Free water clearance becomes negative when the kidney is producing:', '["Dilute urine", "Concentrated urine", "Isotonic urine only", "Protein-rich urine", "Glucose-rich urine"]', 1, 'The kidney is "saving" free water.', 49),
    (v_topic_id, 'Maximal urine concentration requires:', '["Low ADH and no medullary gradient", "High ADH and intact medullary osmotic gradient", "Aldosterone only", "Low renal blood flow only", "No loop of Henle function"]', 1, 'Requires both the gradient and the permeability.', 50),
    (v_topic_id, 'Renal blood flow is related to renal plasma flow by:', '["RBF = RPF × hematocrit", "RBF = RPF ÷ (1 − hematocrit)", "RBF = RPF ÷ hematocrit", "RBF = RPF × (1 − hematocrit)", "EBF = GFR × hematocrit"]', 1, 'RBF includes cellular volume (hematocrit).', 51),
    (v_topic_id, 'If renal plasma flow is 600 mL/min and GFR is 120 mL/min, the filtration fraction is:', '["0.1", "0.2", "0.4", "0.5", "0.8"]', 1, '120/600 = 0.2 (20%).', 52),
    (v_topic_id, 'A decrease in renal perfusion pressure stimulates renin release partly through:', '["Increased stretch of juxtaglomerular cells", "Decreased stretch of juxtaglomerular cells", "Increased atrial pressure", "Increased plasma osmolality", "Decreased aldosterone"]', 1, 'JG cells sense the drop in pressure.', 53),
    (v_topic_id, 'Prostaglandins in the kidney tend to:', '["Constrict the afferent arteriole", "Dilate the afferent arteriole", "Strongly constrict the efferent arteriole", "Decrease renal blood flow in all حالات", "Eliminate autoregulation"]', 1, 'They keep the afferent arteriole open (vasodilation).', 54),
    (v_topic_id, 'NSAIDs may reduce GFR in susceptible patients because they:', '["Increase prostaglandin synthesis", "Block afferent arteriolar vasodilation", "Selectively dilate the efferent arteriole", "Increase renin directly", "Increase Bowman space pressure"]', 1, 'Inhibition of PG synthesis leads to afferent constriction.', 55),
    (v_topic_id, 'ACE inhibitors may reduce GFR in bilateral renal artery stenosis mainly because they:', '["Constrict the afferent arteriole", "Prevent efferent arteriolar constriction by angiotensin II", "Increase glomerular hydrostatic pressure", "Increase filtration fraction", "Increase proximal glucose reabsorption"]', 1, 'Blocking the "exit restriction" drops the filtration pressure.', 56),
    (v_topic_id, 'The filtration barrier normally prevents significant filtration of:', '["Sodium", "Water", "Glucose", "Large negatively charged proteins", "Urea"]', 3, 'Albumin is the classic example.', 57),
    (v_topic_id, 'Podocyte foot processes are part of the:', '["Juxtaglomerular apparatus", "Filtration barrier", "Vasa recta", "Macula densa", "Distal convoluted tubule"]', 1, 'They form slit diaphragms.', 58),
    (v_topic_id, 'Mesangial cell contraction tends to:', '["Increase filtration surface area", "Decrease filtration surface area and reduce GFR", "Increase renal plasma flow directly", "Increase Bowman space pressure", "Increase creatinine secretion"]', 1, 'Contraction reduces the area available for filtration.', 59),
    (v_topic_id, 'The renal threshold for glucose refers to the plasma concentration at which:', '["All filtered glucose is reabsorbed", "Glucose first begins to appear in urine", "GFR becomes maximal", "Insulin secretion begins", "Filtration fraction decreases"]', 1, 'Usually ~180-200 mg/dL.', 60),
    (v_topic_id, 'Transport maximum refers to the:', '["Maximum plasma concentration of a substance", "Maximum rate at which tubules can reabsorb or secrete a substance", "Maximum GFR", "Highest urine flow possible", "Maximum renal plasma flow"]', 1, 'Transporters are fully saturated.', 61),
    (v_topic_id, 'If plasma glucose rises but remains below the transport maximum, urinary glucose will usually:', '["Increase", "Decrease", "Remain absent", "Equal plasma glucose", "Exceed filtered load"]', 2, 'Transporters can still handle the load.', 62),
    (v_topic_id, 'The proximal tubule reabsorbs sodium mainly because of the basolateral:', '["ENaC channel", "Na+/K+ ATPase", "NKCC transporter", "Aquaporin-2 channel", "H+/K+ ATPase"]', 1, 'Creates the gradient for secondary active transport.', 63),
    (v_topic_id, 'Most filtered bicarbonate is reabsorbed in the:', '["Collecting duct", "Distal convoluted tubule", "Proximal tubule", "Thin descending limb", "Vasa recta"]', 2, 'About 80-90% is reabsorbed here.', 64),
    (v_topic_id, 'Carbonic anhydrase inhibitors decrease bicarbonate reabsorption mainly in the:', '["Proximal tubule", "Thick ascending limb", "Distal convoluted tubule", "Collecting duct", "Macula densa"]', 0, 'Acetazolamide acts on the PT.', 65),
    (v_topic_id, 'The thick ascending limb is called the diluting segment because it:', '["Reabsorbs water more than solute", "Reabsorbs solute without water", "Secretes water", "Reabsorbs glucose", "Is impermeable to sodium"]', 1, 'Solutes leave, making the tubular fluid dilute.', 66),
    (v_topic_id, 'The main transporter in the thick ascending limb is:', '["SGLT", "ENaC", "Na+-K+-2Cl− cotransporter", "Na+/H+ exchanger", "Aquaporin-2"]', 2, 'NKCC2 is the target of loop diuretics.', 67),
    (v_topic_id, 'Loop diuretics impair urinary concentrating ability primarily by:', '["Blocking proximal glucose reabsorption", "Reducing medullary hypertonicity", "Increasing ADH release", "Increasing aquaporin insertion", "Stimulating renin suppression directly"]', 1, 'Collapses the osmotic gradient needed for water pull.', 68),
    (v_topic_id, 'The distal convoluted tubule is a major site of:', '["Glucose reabsorption", "Calcium reabsorption regulated by PTH", "Urea recycling", "ADH-mediated water reabsorption only", "Renin secretion"]', 1, 'Major calcium-handling segment.', 69),
    (v_topic_id, 'Thiazide diuretics act primarily on the:', '["Proximal tubule", "Thick ascending limb", "Distal convoluted tubule", "Collecting duct", "Afferent arteriole"]', 2, 'Blocks the NCCT transporter.', 70),
    (v_topic_id, 'Principal cells in the collecting duct normally:', '["Reabsorb bicarbonate and secrete hydrogen", "Reabsorb sodium and water, and secrete potassium", "Reabsorb glucose", "Secrete renin", "Generate the medullary gradient directly"]', 1, 'Responsible for ENaC and ROMK activity.', 71),
    (v_topic_id, 'Intercalated cells are especially important for:', '["Glucose transport", "Acid-base regulation", "Filtration barrier formation", "Renin secretion", "Urea filtration"]', 1, 'Handles H+ and HCO3- secretion.', 72),
    (v_topic_id, 'Type A intercalated cells primarily:', '["Secrete bicarbonate into urine", "Secrete hydrogen ions into urine", "Reabsorb glucose", "Secrete potassium", "Produce ADH"]', 1, 'Active during Acidosis.', 73),
    (v_topic_id, 'Type B intercalated cells primarily:', '["Secrete hydrogen ions", "Reabsorb bicarbonate", "Secrete bicarbonate", "Reabsorb glucose", "Secrete renin"]', 2, 'Active during Alkalosis.', 74),
    (v_topic_id, 'Urea recycling contributes importantly to:', '["Cortical blood flow", "Medullary hypertonicity", "Proximal glucose reabsorption", "Calcium reabsorption", "Filtration fraction"]', 1, 'Urea provides about half the medullary osmolality.', 75),
    (v_topic_id, 'ADH increases urea permeability particularly in the:', '["Proximal tubule", "Thick ascending limb", "Inner medullary collecting duct", "Distal convoluted tubule only", "Afferent arteriole"]', 2, 'Tied to water reabsorption.', 76),
    (v_topic_id, 'In the presence of high ADH, urine osmolality tends to:', '["Fall markedly", "Approach plasma osmolality", "Rise as water is reabsorbed", "Become zero", "Become independent of medullary gradient"]', 2, 'Concentrates the urine.', 77),
    (v_topic_id, 'In the absence of ADH, collecting ducts are relatively:', '["Highly permeable to water", "Impermeable to water", "Highly permeable to glucose", "Major sites of bicarbonate secretion only", "Major sites of inulin secretion"]', 1, 'Water cannot leave the tubule.', 78),
    (v_topic_id, 'Free water clearance is positive when the kidney is producing:', '["Concentrated urine", "Dilute urine", "Isotonic urine only", "Protein-rich urine", "Glucose-rich urine"]', 1, 'Loss of excess water.', 79),
    (v_topic_id, 'Osmolar clearance is best defined as the:', '["Clearance of inulin", "Volume of plasma cleared of osmoles per unit time", "Volume of urine excreted per minute", "Amount of sodium filtered per minute", "Fraction of plasma filtered by the glomerulus"]', 1, 'C_osm = U_osm * V / P_osm.', 80),
    (v_topic_id, 'In severe dehydration, urine sodium is expected to be:', '["High because aldosterone rises", "Low because sodium is avidly reabsorbed", "Fixed at plasma concentration", "Unrelated to aldosterone", "Higher than potassium always"]', 1, 'Kidney saves water and salt.', 81),
    (v_topic_id, 'The kidney contributes to long-term blood pressure regulation mainly through:', '["Controlling heart rate", "Controlling sodium and water balance", "Altering hemoglobin affinity", "Regulating pulmonary resistance", "Changing liver metabolism"]', 1, 'Volume control directly influences pressure.', 82),
    (v_topic_id, 'Pressure natriuresis refers to increased:', '["Water reabsorption with low pressure", "Sodium excretion as arterial pressure rises", "Potassium secretion with low pressure", "Glucose excretion with normal GFR", "Protein filtration as renal blood flow rises"]', 1, 'A safety mechanism against hypertension.', 83),
    (v_topic_id, 'Erythropoietin is produced mainly by:', '["Glomerular endothelial cells", "Interstitial cells in the kidney", "Macula densa", "Principal cells", "Podocytes"]', 1, 'Cells in the peritubular capillaries.', 84),
    (v_topic_id, 'Erythropoietin secretion is stimulated primarily by:', '["Hypercalcemia", "Renal hypoxia", "Hypernatremia", "Increased GFR", "Increased plasma osmolality"]', 1, 'The body needs more oxygen carriers.', 85),
    (v_topic_id, 'One major renal function of vitamin D activation is conversion to:', '["25-hydroxyvitamin D", "1,25-dihydroxyvitamin D", "Calcitonin", "PTH", "Cortisol"]', 1, 'Active form: Calcitriol.', 86),
    (v_topic_id, 'In metabolic alkalosis, the expected compensatory response is:', '["Hyperventilation", "Hypoventilation", "Increased ammonium excretion immediately only", "Increased lactate generation", "No respiratory response occurs"]', 1, 'Retention of CO2 lowers pH.', 87),
    (v_topic_id, 'Persistent vomiting commonly causes metabolic alkalosis because of loss of:', '["Bicarbonate-rich intestinal fluid", "Gastric hydrogen ions", "Potassium from sweat", "Sodium from urine", "Phosphate from stool"]', 1, 'Loss of stomach acid.', 88),
    (v_topic_id, 'Diorrhea commonly causes metabolic acidosis because of loss of:', '["Gastric HCl", "Bicarbonate-rich intestinal fluid", "Sodium chloride only", "Phosphate only", "Urea only"]', 1, 'Loss of bowel buffer.', 89),
    (v_topic_id, 'In metabolic acidosis, ammoniagenesis in the kidney tends to:', '["Decrease", "Increase", "Remain unchanged always", "Stop completely", "Depend only on aldosterone"]', 1, 'Ammonia is a crucial buffer for H+ excretion.', 90),
    (v_topic_id, 'Titratable acid excretion in urine mainly involves buffering by:', '["Hemoglobin", "Phosphate", "Albumin", "Glucose", "Urea"]', 1, 'Urine buffers include phosphate and ammonia.', 91),
    (v_topic_id, 'Hypokalemia tends to increase potassium secretion less because:', '["Aldosterone always falls to zero", "There is less intracellular potassium available for secretion in principal cells", "GFR always rises", "Sodium delivery to distal nephron stops", "ADH blocks ENaC completely"]', 1, 'Mechanism of renal conservation.', 92),
    (v_topic_id, 'Increased distal sodium delivery tends to:', '["Decrease potassium secretion", "Increase potassium secretion", "Eliminate aldosterone action", "Reduce sodium reabsorption", "Reduce hydrogen secretion always"]', 1, 'Na+ uptake drives K+ exit (gradient).', 93),
    (v_topic_id, 'Alkalosis tends to shift potassium:', '["Out of cells", "Into cells", "Into urine without plasma change", "Into bone", "Into GI secretions only"]', 1, 'H+ moves out, K+ moves in.', 94),
    (v_topic_id, 'Hyperkalemia directly increases aldosterone release from the:', '["Zona glomerulosa", "Zona fasciculata", "Zona reticularis", "Posterity pituitary", "Macula densa"]', 0, 'Adrenal cortex response.', 95),
    (v_topic_id, 'The juxtaglomerular apparatus consists of the:', '["Podocytes, mesangial cells, and proximal tubule", "Macula densa, juxtaglomerular cells, and extraglomerular mesangial cells", "Distal tubule, collecting duct, and vasa recta", "Afferent arteriole, efferent arteriole, and renal vein", "Bowman capsule, glomerulus, and ureter"]', 1, 'Key for blood pressure control.', 96),
    (v_topic_id, 'A substance that is freely filtered but neither secreted nor reabsorbed will have a clearance equal to:', '["Renal plasma flow", "GFR", "Renal blood flow", "Urine flow", "Filtration fraction"]', 1, 'The definition of GFR markers.', 97),
    (v_topic_id, 'If a substance is completely cleared from plasma in one pass through the kidneys, its clearance would approximate:', '["GFR", "Renal plasma flow", "Filtration fraction", "Urine flow", "Free water clearance"]', 1, 'The definition of RPF markers.', 98),
    (v_topic_id, 'The fractional excretion of a substance refers to the:', '["Amount filtered per minute", "Fraction of filtered load excreted in urine", "Fraction of renal plasma flow filtered", "Total amount reabsorbed in tubules", "Amount secreted by peritubular capillaries"]', 1, 'FE_sub = (U_sub/P_sub) / (U_cr/P_cr).', 99),
    (v_topic_id, 'If the kidney is excreting less sodium than is filtered, then sodium is undergoing net:', '["Secretion", "Reabsorption", "Filtration failure", "Protein binding", "Osmotic trapping"]', 1, 'Clearance < GFR indicates net reabsorption.', 100);
